#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Projectiles;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.theMagician)]
    public class TheMagicianBuff : BuffDefinition
    {
        public TheMagicianBuff(string nsp, string name) : base(nsp, name)
        {
            AddTriggerFiltered(LevelCallbacks.POST_ENTITY_INIT, PostProjectileInitCallback, EntityTypes.PROJECTILE);
        }
        public override void OnCreate(Buff buff)
        {
            base.OnCreate(buff);
            buff.SetProperty(PROP_TIMER, new FrameTimer(MAX_TIMEOUT));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer == null)
            {
                buff.Remove();
                return;
            }
            if (timer.RunToExpired())
            {
                buff.Remove();
            }
        }
        public void PostProjectileInitCallback(EntityCallbackParams args, CallbackResultVoid result)
        {
            var entity = args.entity;
            var level = entity.Level;
            if (!level.HasBuff(this))
                return;
            if (entity.NoHoming())
                return;
            if (entity.HasBuff<HomingProjectileBuff>())
                return;
            var buff = entity.NewBuff<HomingProjectileBuff>();
            HomingProjectileBuff.SetSpeed(buff, 10);
            entity.AddBuff(buff);
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
        public const int MAX_TIMEOUT = 900;
    }
}
